#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include "kernel.h"
#include <string>

static void check_fp32_contiguous_cuda(
    const torch::Tensor& tensor, const std::string& name) {
    TORCH_CHECK(tensor.is_cuda(), name, " must be a CUDA tensor");
    TORCH_CHECK(
        tensor.dtype() == torch::kFloat32,
        name, " must have float32 dtype, got ", tensor.dtype());
    TORCH_CHECK(tensor.is_contiguous(), name, " must be contiguous");
}

// Destination-passing-style entry. Per definition.json:
//   grad_q_embed     : [seq_len, num_heads=16, head_dim=128] fp32
//   grad_k_embed     : [seq_len, num_heads, head_dim]        fp32
//   q                : [seq_len, num_heads, head_dim]        fp32
//   k                : [seq_len, num_heads, head_dim]        fp32
//   embeddings       : [seq_len, head_dim]                   fp32
//   grad_q           : same as q  (DPS)
//   grad_k           : same as k  (DPS)
//   grad_embeddings  : same as embeddings (DPS)
//
// head_dim = 128 and num_heads = 16 are pinned. seq_len is
// workload-variable.
void run(
    const torch::Tensor& grad_q_embed,
    const torch::Tensor& grad_k_embed,
    const torch::Tensor& q,
    const torch::Tensor& k,
    const torch::Tensor& embeddings,
    torch::Tensor grad_q,
    torch::Tensor grad_k,
    torch::Tensor grad_embeddings
) {
    TORCH_CHECK(grad_q_embed.dim() == 3,
                "grad_q_embed must be 3D [S, H, D]");
    TORCH_CHECK(grad_k_embed.dim() == 3,
                "grad_k_embed must be 3D [S, H, D]");
    TORCH_CHECK(q.dim() == 3, "q must be 3D [S, H, D]");
    TORCH_CHECK(k.dim() == 3, "k must be 3D [S, H, D]");
    TORCH_CHECK(embeddings.dim() == 2,
                "embeddings must be 2D [S, D]");
    TORCH_CHECK(grad_q.dim() == 3, "grad_q must be 3D");
    TORCH_CHECK(grad_k.dim() == 3, "grad_k must be 3D");
    TORCH_CHECK(grad_embeddings.dim() == 2,
                "grad_embeddings must be 2D");

    constexpr int64_t kHeadDim = 128;
    constexpr int64_t kNumHeads = 16;
    TORCH_CHECK(grad_q_embed.size(2) == kHeadDim,
                "head_dim must be ", kHeadDim,
                " for problem_019, got ", grad_q_embed.size(2));
    TORCH_CHECK(grad_q_embed.size(1) == kNumHeads,
                "num_heads must be ", kNumHeads,
                " for problem_019, got ", grad_q_embed.size(1));
    TORCH_CHECK(q.sizes() == grad_q_embed.sizes(),
                "q shape must match grad_q_embed");
    TORCH_CHECK(k.sizes() == grad_k_embed.sizes(),
                "k shape must match grad_k_embed");
    TORCH_CHECK(grad_q.sizes() == grad_q_embed.sizes(),
                "grad_q shape must match grad_q_embed");
    TORCH_CHECK(grad_k.sizes() == grad_k_embed.sizes(),
                "grad_k shape must match grad_k_embed");
    TORCH_CHECK(embeddings.size(0) == grad_q_embed.size(0) &&
                embeddings.size(1) == kHeadDim,
                "embeddings must be [seq_len, head_dim]");
    TORCH_CHECK(grad_embeddings.sizes() == embeddings.sizes(),
                "grad_embeddings shape must match embeddings");
    TORCH_CHECK(grad_q_embed.size(0) == grad_k_embed.size(0),
                "Q and K must agree on seq_len");

    check_fp32_contiguous_cuda(grad_q_embed, "grad_q_embed");
    check_fp32_contiguous_cuda(grad_k_embed, "grad_k_embed");
    check_fp32_contiguous_cuda(q, "q");
    check_fp32_contiguous_cuda(k, "k");
    check_fp32_contiguous_cuda(embeddings, "embeddings");
    check_fp32_contiguous_cuda(grad_q, "grad_q");
    check_fp32_contiguous_cuda(grad_k, "grad_k");
    check_fp32_contiguous_cuda(grad_embeddings, "grad_embeddings");

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    problem_019_grad_x_launcher(grad_q_embed, embeddings, grad_q, stream);
    problem_019_grad_x_launcher(grad_k_embed, embeddings, grad_k, stream);
    problem_019_grad_emb_launcher(
        grad_q_embed, grad_k_embed, q, k, embeddings,
        grad_embeddings, stream);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def(
        "run", &run,
        "fp32 Vision 3D RoPE backward: per-element grad_q / grad_k "
        "(two launches of one launcher) + per-(s) reduction "
        "grad_embeddings (one launch). head_dim=128, num_heads=16 "
        "pinned.");
}

#include "kernel.h"
#include <cuda_runtime.h>

// fp32 Vision 3D RoPE backward.
//
// Kernel A computes grad_q or grad_k per element using the
// rotate-half-backward pattern. Cos/sin tables are derived
// in-kernel from the `embeddings[seq_len, head_dim]` tensor.
//
// Kernel B accumulates grad_embeddings[s, d] by summing
// per-head contributions of (grad_q_embed * q) + (grad_k_embed * k)
// for the cos-derivative branch, and the rotated-h variants for
// the sin-derivative branch, then mixes them via cos(emb) and
// sin(emb).

namespace {

constexpr int kHeadDim = 128;
constexpr int kHalfHeadDim = 64;
constexpr int kBlockThreads = kHeadDim;
constexpr int kReductionThreads = 256;

__device__ inline void resolve_partner(
    int d, int& partner_d, float& partner_sign_fwd) {
    if (d < kHalfHeadDim) {
        partner_d = d + kHalfHeadDim;
        partner_sign_fwd = -1.0f;
    } else {
        partner_d = d - kHalfHeadDim;
        partner_sign_fwd = 1.0f;
    }
}

__global__ void __launch_bounds__(kBlockThreads, 8)
problem_019_grad_x_kernel(
    const float* __restrict__ grad_x_embed,
    const float* __restrict__ embeddings,
    float* __restrict__ grad_x,
    int num_heads,
    int seq_len) {

    // Grid: (num_heads, seq_len). One CTA per (s, h) row.
    const int h = blockIdx.x;
    const int s = blockIdx.y;
    const int d = threadIdx.x;

    int partner_d;
    float partner_sign_fwd;
    resolve_partner(d, partner_d, partner_sign_fwd);

    // Row offsets:
    //   grad_x_embed and grad_x: [S, H, D] indexed as
    //     (s*num_heads + h)*head_dim + d
    //   embeddings: [S, D] indexed as s*head_dim + d
    const int row_offset = (s * num_heads + h) * kHeadDim;
    const int emb_offset = s * kHeadDim;

    const float g_d       = grad_x_embed[row_offset + d];
    const float g_partner = grad_x_embed[row_offset + partner_d];
    const float emb_d     = embeddings[emb_offset + d];
    const float emb_par   = embeddings[emb_offset + partner_d];
    const float cos_d     = cosf(emb_d);
    const float sin_par   = sinf(emb_par);

    grad_x[row_offset + d] =
        g_d * cos_d - partner_sign_fwd * g_partner * sin_par;
}

__global__ void __launch_bounds__(kReductionThreads, 4)
problem_019_grad_emb_kernel(
    const float* __restrict__ grad_q_embed,
    const float* __restrict__ grad_k_embed,
    const float* __restrict__ q,
    const float* __restrict__ k,
    const float* __restrict__ embeddings,
    float* __restrict__ grad_embeddings,
    int num_heads,
    int seq_len) {

    // Grid: (seq_len,). One CTA per s. BLOCK_THREADS = 256 stride
    // loops over head_dim = 128.
    const int s = blockIdx.x;
    const int tid = threadIdx.x;
    const int emb_offset = s * kHeadDim;

    for (int d = tid; d < kHeadDim; d += kReductionThreads) {
        int partner_d;
        float partner_sign_fwd;
        resolve_partner(d, partner_d, partner_sign_fwd);

        float acc_cos = 0.0f;
        float acc_sin = 0.0f;
        for (int h = 0; h < num_heads; ++h) {
            const int qk_row_offset =
                (s * num_heads + h) * kHeadDim;
            const float g_q      = grad_q_embed[qk_row_offset + d];
            const float g_k      = grad_k_embed[qk_row_offset + d];
            const float q_d      = q[qk_row_offset + d];
            const float k_d      = k[qk_row_offset + d];
            const float q_par    = q[qk_row_offset + partner_d];
            const float k_par    = k[qk_row_offset + partner_d];
            acc_cos += g_q * q_d + g_k * k_d;
            acc_sin += g_q * q_par + g_k * k_par;
        }
        // grad_sin_total = partner_sign_fwd * Σ_h(g * x_partner_via_rotate_half)
        acc_sin *= partner_sign_fwd;

        const float emb_d   = embeddings[emb_offset + d];
        const float cos_e_d = cosf(emb_d);
        const float sin_e_d = sinf(emb_d);
        grad_embeddings[emb_offset + d] =
            -acc_cos * sin_e_d + acc_sin * cos_e_d;
    }
}

}  // namespace

void problem_019_grad_x_launcher(
    const torch::Tensor& grad_x_embed,
    const torch::Tensor& embeddings,
    torch::Tensor& grad_x,
    cudaStream_t stream) {

    const int seq_len = static_cast<int>(grad_x_embed.size(0));
    const int num_heads = static_cast<int>(grad_x_embed.size(1));

    dim3 grid(num_heads, seq_len);
    dim3 block(kBlockThreads);

    problem_019_grad_x_kernel<<<grid, block, 0, stream>>>(
        grad_x_embed.data_ptr<float>(),
        embeddings.data_ptr<float>(),
        grad_x.data_ptr<float>(),
        num_heads,
        seq_len);
}

void problem_019_grad_emb_launcher(
    const torch::Tensor& grad_q_embed,
    const torch::Tensor& grad_k_embed,
    const torch::Tensor& q,
    const torch::Tensor& k,
    const torch::Tensor& embeddings,
    torch::Tensor& grad_embeddings,
    cudaStream_t stream) {

    const int seq_len = static_cast<int>(grad_q_embed.size(0));
    const int num_heads = static_cast<int>(grad_q_embed.size(1));

    dim3 grid(seq_len);
    dim3 block(kReductionThreads);

    problem_019_grad_emb_kernel<<<grid, block, 0, stream>>>(
        grad_q_embed.data_ptr<float>(),
        grad_k_embed.data_ptr<float>(),
        q.data_ptr<float>(),
        k.data_ptr<float>(),
        embeddings.data_ptr<float>(),
        grad_embeddings.data_ptr<float>(),
        num_heads,
        seq_len);
}

#pragma once

#ifndef PROBLEM_019_VISION_3D_ROPE_BACKWARD_KERNEL_H
#define PROBLEM_019_VISION_3D_ROPE_BACKWARD_KERNEL_H

#include <cuda_runtime.h>
#include <torch/extension.h>

// Host launcher set for the fp32 Vision 3D RoPE backward kernels.
//
// Forward (from definition):
//   cos = cos(embeddings)               # [S, D]
//   sin = sin(embeddings)               # [S, D]
//   q_embed = q * cos + rotate_half(q) * sin
//   k_embed = k * cos + rotate_half(k) * sin
// where rotate_half(x)[d] = -x[d + half_dim] for d < half_dim
//                         =  x[d - half_dim] for d >= half_dim
//
// Backward:
//   grad_x[s, h, d] = grad_x_embed[s, h, d] * cos(emb[s, d])
//                   - partner_sign_fwd[d] * grad_x_embed[s, h, partner_d]
//                     * sin(emb[s, partner_d])
//   grad_embeddings[s, d] = -grad_cos_total[s, d] * sin(emb[s, d])
//                         +  grad_sin_total[s, d] * cos(emb[s, d])
//   where grad_cos_total[s, d] = Σ_h (g_q[s,h,d]*q[s,h,d] + g_k[s,h,d]*k[s,h,d])
//         grad_sin_total[s, d] = partner_sign_fwd[d] *
//                                Σ_h (g_q[s,h,d]*q[s,h,partner_d]
//                                    + g_k[s,h,d]*k[s,h,partner_d])
//   partner_sign_fwd[d] = -1 for d < half_dim, +1 for d >= half_dim
//
// head_dim = 128 and num_heads = 16 are pinned by the problem
// definition; half_head_dim = 64. seq_len is workload-variable.
//
// Two kernels driven by one DPS entry:
//   * problem_019_grad_x_launcher invoked TWICE — once for
//     (grad_q_embed, q, grad_q), once for (grad_k_embed, k, grad_k).
//   * problem_019_grad_emb_launcher invoked ONCE; per-(s) row CTA
//     accumulating per-(d) sums over the num_heads axis.
void problem_019_grad_x_launcher(
    const torch::Tensor& grad_x_embed,
    const torch::Tensor& embeddings,
    torch::Tensor& grad_x,
    cudaStream_t stream);

void problem_019_grad_emb_launcher(
    const torch::Tensor& grad_q_embed,
    const torch::Tensor& grad_k_embed,
    const torch::Tensor& q,
    const torch::Tensor& k,
    const torch::Tensor& embeddings,
    torch::Tensor& grad_embeddings,
    cudaStream_t stream);

#endif  // PROBLEM_019_VISION_3D_ROPE_BACKWARD_KERNEL_H
